import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import test from "node:test";

import { GoEngine } from "../src/game/goEngine.js";
import { buildReplayFrames } from "../src/game/replay.js";
import { RoomEngine } from "../src/multiplayer/roomEngine.js";

// Generated by scripts/generate-go-golden.mjs from the engine as it was
// before the topology refactor. Never regenerate it to make this test pass.
const FIXTURE_URL = new URL("./fixtures/go-golden-v1.json", import.meta.url);
const FIXTURE_TEXT = readFileSync(FIXTURE_URL, "utf8");
const CELL = { ".": null, B: "black", W: "white" };

/** Boards are stored as rows of "."/"B"/"W"; decode them back to arrays. */
function decodeBoards(key, value) {
  if (
    key === "board" &&
    Array.isArray(value) &&
    value.every((row) => typeof row === "string")
  ) {
    return value.map((row) => [...row].map((cell) => {
      assert.ok(Object.hasOwn(CELL, cell), `bad board cell ${cell}`);
      return CELL[cell];
    }));
  }
  return value;
}

const fixture = JSON.parse(FIXTURE_TEXT, decodeBoards);

function sha256(text) {
  return createHash("sha256").update(text).digest("hex");
}

/** Re-apply recorded replay events through the public engine API. */
function replayGame(settings, events) {
  const game = new GoEngine(settings);
  for (const event of events) {
    let result;
    if (event.type === "play") result = game.play(event.row, event.col);
    else if (event.type === "pass") result = game.pass();
    else if (event.type === "toggle_dead") result = game.toggleDead(event.row, event.col);
    else if (event.type === "finish_scoring") result = game.finishScoring(event.rule);
    else if (event.type === "resume_play") result = game.resumePlay(event.nextPlayer);
    else if (event.type === "resign") result = game.resign(event.color);
    else assert.fail(`unknown event ${event.type}`);
    assert.equal(result.ok, true, `${event.type} must stay legal`);
  }
  return game;
}

test("the golden fixture is small and covers every topology, rectangle and seam captures", () => {
  assert.ok(FIXTURE_TEXT.length < 300_000, `fixture is ${FIXTURE_TEXT.length} bytes`);
  assert.equal(fixture.version, 1);
  assert.equal(fixture.games.length, 9);
  for (const topology of ["cylinder", "torus", "mobius"]) {
    const games = fixture.games.filter((game) => game.settings.topology === topology);
    assert.equal(games.length, 3);
    assert.ok(games.some((game) => game.settings.width !== game.settings.height));
    assert.ok(games.every((game) => game.stats.seamCaptures > 0));
  }
  assert.ok(fixture.room.stats.seamCaptures > 0);
});

for (const record of fixture.games) {
  test(`golden Go game ${record.id} replays byte-identically`, () => {
    const game = replayGame(record.settings, record.exportState.replay.events);

    // JSON text comparison also pins key order (getState/exportState bytes).
    assert.equal(game.serialize(), JSON.stringify(record.exportState));
    assert.deepEqual(game.exportState(), record.exportState);
    assert.deepEqual(game.score(), record.score);
    assert.deepEqual(game.suggestDeadStones(), record.suggestedDeadStones);

    const frames = buildReplayFrames(game.getReplayState());
    assert.deepEqual(frames.steps, record.frames.steps);
    assert.equal(frames.complete, record.frames.complete);
    assert.equal(frames.frames.length, record.frames.frameCount);
    assert.deepEqual(frames.frames.at(-1), record.frames.finalFrame);
    assert.equal(sha256(JSON.stringify(frames.frames)), record.frames.framesSha256);

    if (record.afterUndo) {
      for (let count = 0; count < 3 && game.canUndo(); count += 1) {
        assert.equal(game.undo().ok, true);
      }
      const afterUndo = game.exportState();
      assert.deepEqual(afterUndo.lastMove, record.afterUndo.lastMove);
      assert.equal(afterUndo.replay.events.length, record.afterUndo.eventCount);
      assert.equal(afterUndo.undoHistory.length, record.afterUndo.undoDepth);
      assert.equal(sha256(JSON.stringify(afterUndo)), record.afterUndo.sha256);
    }
  });

  test(`golden Go game ${record.id} restores from the stored state`, () => {
    const restored = GoEngine.fromState(structuredClone(record.exportState));
    assert.equal(restored.serialize(), JSON.stringify(record.exportState));
    const fromJson = GoEngine.fromState(JSON.stringify(record.exportState));
    assert.deepEqual(fromJson.exportState(), record.exportState);
    // Replays rebuilt from the stored replay match the live engine too.
    const frames = buildReplayFrames(structuredClone(record.exportState.replay));
    assert.equal(sha256(JSON.stringify(frames.frames)), record.frames.framesSha256);
  });
}

test("golden online room serializes and fingerprints byte-identically", () => {
  const { settings, incarnationId, actions } = fixture.room;
  const room = RoomEngine.create(structuredClone(settings));
  room.state.incarnationId = incarnationId;
  room.join({
    name: "White",
    role: "player",
    playerId: "white-player",
    tokenHash: "b".repeat(64),
    now: settings.now + 1,
  });
  const positionTokens = [room.snapshot(settings.now + 2).positionToken];
  for (const action of actions) {
    room.applyAction(structuredClone(action));
    positionTokens.push(room.snapshot(action.now).positionToken);
  }
  assert.deepEqual(positionTokens, fixture.room.positionTokens);
  assert.equal(JSON.stringify(room.serialize()), JSON.stringify(fixture.room.serialized));

  const restored = RoomEngine.restore(structuredClone(fixture.room.serialized));
  assert.equal(
    restored.snapshot(actions.at(-1).now).positionToken,
    fixture.room.positionTokens.at(-1),
  );
  assert.equal(JSON.stringify(restored.serialize()), JSON.stringify(fixture.room.serialized));
});
